<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { ArrowDownUp, Box, ChevronDown, ChevronUp, Copy, Eye, Link2, Pencil, Plus, Search, X } from 'lucide-vue-next'
import { api, listData } from '../api'

const templates = ref([]), suppliers = ref([]), skuRows = ref([]), query = ref(''), policy = ref(''), loading = ref(true), saving = ref(false)
const formOpen = ref(false), detailOpen = ref(false), linkedOpen = ref(false), editingId = ref(null), active = ref(null)
const sort = reactive({ key: 'name', direction: 'asc' })
const toast = reactive({ text: '', error: false })
const form = reactive({ name: '', supplier: '', carton_length: '', carton_width: '', carton_height: '', carton_tare_weight: '', partial_carton_policy: 'SAME_CARTON', mixed_pack_allowed: false, active: true, description: '' })
const policyLabels = { SAME_CARTON: '整箱优先', REPACK: '尾箱待确认', MANUAL: '人工装箱' }
const filtered = computed(() => templates.value.filter(x => (!query.value || `${x.name} ${x.supplier_name || ''}`.toLowerCase().includes(query.value.toLowerCase())) && (!policy.value || x.partial_carton_policy === policy.value)))
const sorted = computed(() => [...filtered.value].sort((left, right) => {
  const value = row => ({ supplier: row.supplier_name || '', policy: policyLabels[row.partial_carton_policy] || '', mixed: row.mixed_pack_allowed ? 1 : 0, linked: Number(row.linked_sku_count || 0), volume: Number(row.cbm || 0), weight: Number(row.carton_tare_weight || 0) }[sort.key] ?? row[sort.key] ?? '')
  const a = value(left), b = value(right)
  const comparison = typeof a === 'number' && typeof b === 'number' ? a - b : String(a).localeCompare(String(b), 'zh-CN', { numeric: true })
  return sort.direction === 'asc' ? comparison : -comparison
}))
const linkedSkus = computed(() => active.value ? skuRows.value.filter(x => Number(x.packaging?.template) === Number(active.value.id)) : [])
function notice(text, error = false) { Object.assign(toast, { text, error }); setTimeout(() => toast.text = '', 2600) }
function resetForm(x = null) { Object.assign(form, { name: x?.name || '', supplier: x?.supplier || '', carton_length: x?.carton_length || '', carton_width: x?.carton_width || '', carton_height: x?.carton_height || '', carton_tare_weight: x?.carton_tare_weight || '', partial_carton_policy: x?.partial_carton_policy || 'SAME_CARTON', mixed_pack_allowed: x?.mixed_pack_allowed || false, active: x?.active ?? true, description: x?.description || '' }) }
async function load() { loading.value = true; try { [templates.value, suppliers.value, skuRows.value] = await Promise.all([api.get('/packaging-templates/').then(listData), api.get('/suppliers/').then(listData), api.get('/skus/').then(listData)]) } catch (e) { notice(e.message, true) } finally { loading.value = false } }
function create() { editingId.value = null; resetForm(); formOpen.value = true }
function edit(x) { editingId.value = x.id; resetForm(x); formOpen.value = true }
function details(x) { active.value = x; detailOpen.value = true }
function linked(x) { active.value = x; linkedOpen.value = true }
function setSort(key) { if (sort.key === key) sort.direction = sort.direction === 'asc' ? 'desc' : 'asc'; else Object.assign(sort, { key, direction: 'asc' }) }
function sortIcon(key) { return sort.key !== key ? ArrowDownUp : sort.direction === 'asc' ? ChevronUp : ChevronDown }
async function save() { saving.value = true; const data = { ...form, supplier: form.supplier || null }; try { editingId.value ? await api.put(`/packaging-templates/${editingId.value}/`, data) : await api.post('/packaging-templates/', data); formOpen.value = false; await load(); notice(editingId.value ? '包装模板已更新' : '包装模板已创建') } catch (e) { notice(e.message, true) } finally { saving.value = false } }
async function duplicate(x) { const { id, code, qty_per_carton, created_at, updated_at, cbm, supplier_name, linked_sku_count, ...data } = x; try { await api.post('/packaging-templates/', { ...data, name: `${x.name}（副本）` }); await load(); notice('已生成可编辑的新模板') } catch (e) { notice(e.message, true) } }
onMounted(load)
</script>

<template>
  <section class="packaging-page">
    <div class="page-head"><div><h2>包装管理</h2><p>管理通用包装模板，维护供应商、尺寸和装箱规则，并查看关联的 SKU。</p></div><button class="btn btn-primary" @click="create"><Plus :size="16" /> 新建模板</button></div>
    <div class="panel list-panel"><div class="toolbar"><div class="search-box"><Search :size="17" /><input v-model="query" placeholder="搜索模板名称或供应商" /></div><label>散箱策略 <select v-model="policy"><option value="">全部</option><option v-for="(label,key) in policyLabels" :key="key" :value="key">{{ label }}</option></select></label></div><div v-if="loading" class="loading"><div class="spinner" /></div><div v-else-if="!filtered.length" class="empty"><Box :size="34" /><h3>没有匹配的包装模板</h3><p>点击“新建模板”建立首个包装资料。</p></div><div v-else class="table-wrap"><table class="data-table"><thead><tr><th v-for="column in [{key:'name',label:'模板名称'},{key:'supplier',label:'供应商'},{key:'carton_length',label:'长'},{key:'carton_width',label:'宽'},{key:'carton_height',label:'高'},{key:'volume',label:'体积 (m³)'},{key:'weight',label:'外箱皮重'},{key:'policy',label:'散箱策略'},{key:'mixed',label:'允许混装'},{key:'linked',label:'关联 SKU'}]" :key="column.key"><button class="sort-head" :class="{ active: sort.key === column.key }" @click="setSort(column.key)">{{ column.label }}<component :is="sortIcon(column.key)" :size="13" /></button></th><th>操作</th></tr></thead><tbody><tr v-for="x in sorted" :key="x.id"><td><button class="text-link primary-cell" @click="details(x)">{{ x.name }}</button></td><td>{{ x.supplier_name || '未指定' }}</td><td>{{ x.carton_length }}</td><td>{{ x.carton_width }}</td><td>{{ x.carton_height }}</td><td>{{ Number(x.cbm || 0).toFixed(4) }}</td><td>{{ x.carton_tare_weight }} kg</td><td><span class="tag">{{ policyLabels[x.partial_carton_policy] }}</span></td><td>{{ x.mixed_pack_allowed ? '是' : '否' }}</td><td><button class="text-link" @click="linked(x)">{{ x.linked_sku_count || 0 }} 个 SKU</button></td><td><div class="table-actions"><button class="mini-btn" title="查看详情" @click="details(x)"><Eye :size="15" /></button><button class="mini-btn" title="复制模板" @click="duplicate(x)"><Copy :size="15" /></button><button class="mini-btn" title="编辑" @click="edit(x)"><Pencil :size="15" /></button></div></td></tr></tbody></table></div><div v-if="!loading && filtered.length" class="table-foot">共 {{ filtered.length }} 条包装模板</div></div>

    <div v-if="formOpen" class="modal-backdrop" @mousedown.self="formOpen=false"><form class="modal template-form" @submit.prevent="save"><div class="modal-head"><div><h3>{{ editingId ? '编辑包装模板' : '新建包装模板' }}</h3><p>模板可被多个 SKU 引用；装箱数在 SKU 管理中按 SKU 单独维护。</p></div><button type="button" class="mini-btn" @click="formOpen=false"><X :size="17" /></button></div><div class="modal-body"><div class="form-grid"><div class="field"><label>模板名称 <em>*</em></label><input v-model.trim="form.name" required /></div><div class="field"><label>包装供应商</label><select v-model="form.supplier"><option value="">未指定</option><option v-for="s in suppliers" :key="s.id" :value="s.id">{{ s.name }}</option></select></div><div class="field"><label>散箱策略</label><select v-model="form.partial_carton_policy"><option v-for="(label,key) in policyLabels" :key="key" :value="key">{{ label }}</option></select></div><div class="field"><label>长 (cm) <em>*</em></label><input v-model="form.carton_length" type="number" min="0.01" step="0.01" required /></div><div class="field"><label>宽 (cm) <em>*</em></label><input v-model="form.carton_width" type="number" min="0.01" step="0.01" required /></div><div class="field"><label>高 (cm) <em>*</em></label><input v-model="form.carton_height" type="number" min="0.01" step="0.01" required /></div><div class="field"><label>外箱皮重 (kg)</label><input v-model="form.carton_tare_weight" type="number" min="0" step="0.001" required /></div><label class="check"><input v-model="form.mixed_pack_allowed" type="checkbox" /> 允许混装</label><label class="check"><input v-model="form.active" type="checkbox" /> 启用模板</label><div class="field full"><label>备注</label><textarea v-model="form.description" placeholder="适用范围、材质或采购说明" /></div></div></div><div class="modal-foot"><button type="button" class="btn btn-secondary" @click="formOpen=false">取消</button><button class="btn btn-primary" :disabled="saving">{{ saving ? '保存中...' : '保存模板' }}</button></div></form></div>

    <div v-if="detailOpen && active" class="drawer-backdrop" @mousedown.self="detailOpen=false"><aside class="drawer"><div class="drawer-head"><h3>模板详情</h3><button class="mini-btn" @click="detailOpen=false"><X :size="18" /></button></div><div class="drawer-body"><h4>基本信息</h4><dl><dt>模板名</dt><dd>{{ active.name }}</dd><dt>包装供应商</dt><dd>{{ active.supplier_name || '未指定' }}</dd><dt>长 × 宽 × 高</dt><dd>{{ active.carton_length }} × {{ active.carton_width }} × {{ active.carton_height }} cm</dd><dt>外箱皮重</dt><dd>{{ active.carton_tare_weight }} kg</dd><dt>体积</dt><dd>{{ active.cbm }} m³</dd><dt>散箱策略</dt><dd>{{ policyLabels[active.partial_carton_policy] }}</dd><dt>允许混装</dt><dd>{{ active.mixed_pack_allowed ? '是' : '否' }}</dd></dl><div class="figure"><h4>尺寸示意图</h4><div class="carton"><i /></div><span>长 {{ active.carton_length }} cm　宽 {{ active.carton_width }} cm　高 {{ active.carton_height }} cm</span></div><p v-if="active.description" class="description">{{ active.description }}</p></div><div class="drawer-foot"><button class="btn btn-secondary" @click="detailOpen=false">关闭</button><button class="btn btn-secondary" @click="edit(active);detailOpen=false">编辑</button><button class="btn btn-primary" @click="detailOpen=false;linked(active)"><Link2 :size="15" /> 关联 SKU</button></div></aside></div>
    <div v-if="linkedOpen && active" class="modal-backdrop" @mousedown.self="linkedOpen=false"><div class="modal linked-modal"><div class="modal-head"><div><h3>{{ active.name }} · 关联 SKU</h3><p>使用此包装模板的 SKU。</p></div><button class="mini-btn" @click="linkedOpen=false"><X :size="17" /></button></div><div class="modal-body"><div v-if="!linkedSkus.length" class="empty compact"><p>暂未关联 SKU。</p></div><table v-else class="data-table"><thead><tr><th>SKU</th><th>产品</th><th>包装状态</th></tr></thead><tbody><tr v-for="sku in linkedSkus" :key="sku.id"><td class="primary-cell">{{ sku.sku }}</td><td>{{ sku.product_name }}</td><td>{{ sku.packaging?.status }}</td></tr></tbody></table></div><div class="modal-foot"><button class="btn btn-secondary" @click="linkedOpen=false">关闭</button></div></div></div><div v-if="toast.text" class="toast" :class="{error:toast.error}">{{ toast.text }}</div>
  </section>
</template>

<style scoped>
.list-panel{padding:0}.toolbar{padding:17px 20px;display:flex;gap:18px;align-items:center;border-bottom:1px solid var(--line)}.toolbar label{display:flex;align-items:center;gap:8px;color:var(--muted);font-size:13px}.toolbar select,.field input,.field select,.field textarea{border:1px solid var(--line);border-radius:7px;background:#fff}.toolbar select{height:36px;padding:0 8px}.sort-head{display:inline-flex;align-items:center;gap:4px;border:0;background:transparent;padding:0;color:inherit;font:inherit;font-weight:inherit;cursor:pointer;white-space:nowrap}.sort-head:hover,.sort-head.active{color:var(--green-2)}.text-link{border:0;background:none;padding:0;color:var(--green-2);font:inherit;cursor:pointer;text-align:left}.text-link:hover{text-decoration:underline}.text-link small{display:block;margin-top:3px;color:#81908b;font-size:11px}.tag{display:inline-block;padding:4px 8px;border-radius:99px;background:#edf4f1;color:#43665a;font-size:12px}.table-foot{padding:13px 20px;border-top:1px solid var(--line);color:var(--muted);font-size:13px}.template-form{width:min(720px,calc(100vw - 28px))}.modal-head>div p{margin:4px 0 0;color:var(--muted);font-size:12px;font-weight:400}.form-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:16px}.field{display:flex;flex-direction:column;gap:7px}.field.full{grid-column:1/-1}.field label{font-size:13px;font-weight:650;color:#3d5049}.field em{color:var(--danger);font-style:normal}.field input,.field select{height:38px;padding:0 10px}.field textarea{min-height:78px;padding:9px 10px;resize:vertical}.check{display:flex;align-items:center;gap:8px;padding-top:25px;color:#40534c;font-size:13px}.check input{accent-color:var(--green-2)}.drawer-backdrop{position:fixed;inset:0;z-index:20;background:#18322a44;display:flex;justify-content:flex-end}.drawer{width:min(430px,100vw);height:100%;display:flex;flex-direction:column;background:white;box-shadow:-8px 0 32px #18322a22}.drawer-head,.drawer-foot{padding:18px 22px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line)}.drawer-head h3{margin:0;font-size:18px}.drawer-body{padding:20px 26px;overflow:auto}.drawer-body h4{margin:0 0 13px;font-size:14px}.drawer-body dl{display:grid;grid-template-columns:105px 1fr;row-gap:12px;margin:0}.drawer-body dt{color:var(--muted);font-size:13px}.drawer-body dd{margin:0;font-size:13px}.figure{margin-top:26px;padding-top:20px;border-top:1px solid var(--line);text-align:center;color:#705037;font-size:11px}.carton{position:relative;width:180px;height:108px;margin:18px auto;background:linear-gradient(135deg,#e7c79e,#c99662);border:1px solid #a87445;transform:skewY(-8deg)}.carton i{position:absolute;left:50%;top:0;width:31px;height:100%;background:#f1dbbc;border-left:1px solid #ae7d4a;border-right:1px solid #ae7d4a;transform:translateX(-50%)}.description{padding:12px;background:#f7faf8;color:#53665f;font-size:13px;line-height:1.6}.drawer-foot{margin-top:auto;border-top:1px solid var(--line);border-bottom:0;gap:9px;justify-content:flex-end}.linked-modal{width:min(680px,calc(100vw - 28px))}.linked-modal .data-table{width:100%}.compact{padding:26px}@media(max-width:680px){.toolbar{flex-direction:column;align-items:stretch}.toolbar label{justify-content:space-between}.form-grid{grid-template-columns:1fr}.check{padding-top:0}}
</style>
